Here is an interactive learning interface designed for vocabulary review, containing ten flip flashcards and visual progress indicators to track your study session.

<a2ui-json>
{
  "version": "v0.9.1",
  "createSurface": {
    "surfaceId": "vocabulary-flashcards-surface",
    "catalogId": "https://a2uicatalog.ai/catalog/c-learning.json",
    "theme": {
      "primaryColor": "#6366f1"
    }
  }
}
</a2ui-json>

<a2ui-json>
{
  "version": "v0.9.1",
  "updateComponents": {
    "surfaceId": "vocabulary-flashcards-surface",
    "components": [
      {
        "id": "root",
        "component": "page_header",
        "title": "Advanced Vocabulary Mastery",
        "subtitle": "Flip through these 10 high-yield vocabulary cards to strengthen your lexicon.",
        "icon": "📚",
        "tag": "Study Session",
        "accent": "#6366f1"
      },
      {
        "id": "progress-section",
        "component": "columns",
        "cols": 2,
        "gap": "1.5rem",
