        "items": [
          {
            "blocks": [
              {
                "id": "progress-stat-card",
                "component": "highlight_box",
                "title": "Session Goal",
                "text": "Review all 10 terms. Test your recall before flipping to reveal the definition.",
                "icon": "🎯",
                "accent": "#6366f1",
                "style": "outline"
              }
            ]
          },
          {
            "blocks": [
              {
                "id": "progress-tracker",
                "component": "progress_bar",
                "value": 100,
                "label": "Cards Reviewed Status",
                "accent": "#10b981",
                "show_percent": "true",
                "caption": "10 of 10 Cards Loaded Below"
              }
            ]
          }
        ]
      },
      {
        "id": "deck-intro",
        "component": "heading",
        "text": "Interactive Flashcard Deck"
      },
      {
        "id": "main-deck",
        "component": "flashcard_deck",
        "accent": "#6366f1",
        "label_front": "LATIN/GREEK ROOT & TERM",
        "label_back": "DEFINITION & CONTEXT",
        "cards": [
          {
            "front": "Ephemeral",
            "back": "Lasting for a very short time.\n\nExample: 'The ephemeral joy of a beautiful sunset.'"
          },
          {
            "front": "Capricious",
            "back": "Given to sudden and unaccountable changes of mood or behavior.\n\nExample: 'The capricious administration constantly shifted policies.'"
          },
          {
            "front": "Pernicious",
            "back": "Having a harmful effect, especially in a gradual or subtle way.\n\nExample: 'The pernicious influence of rumors undermined team trust.'"
          },
          {
            "front": "Alacrity",
            "back": "Brisk and cheerful readiness.\n\nExample: 'She accepted the job invitation with alacrity.'"
          },
          {
            "front": "Obfuscate",
            "back": "To render obscure, unclear, or unintelligible.\n\nExample: 'The jargon was used to obfuscate the real issues.'"
          },
          {
            "front": "Loquacious",
            "back": "Tending to talk a great deal; extremely talkative.\n\nExample: 'The loquacious host kept the party lively but exhausted.'"
          },
          {
            "front": "Pragmatic",
            "back": "Dealing with things sensibly and realistically based on practical considerations.\n\nExample: 'A pragmatic approach to solving the budget crisis.'"
          },
          {
            "front": "Fastidious",
            "back": "Very attentive to and concerned about accuracy and detail.\n\nExample: 'The architect was fastidious about the structural layout.'"
          },
          {
            "front": "Taciturn",
            "back": "Reserved or uncommunicative in speech; saying little.\n\nExample: 'A quiet, taciturn man who spoke only when necessary.'"
          },
          {
            "front": "Mellifluous",
            "back": "Sweet or musical; pleasant to hear.\n\nExample: 'The singer's mellifluous voice filled the concert hall.'"
          }
        ]
      },
      {
        "id": "knowledge-check-heading",
        "component": "heading",
        "text": "Quick Comprehension Pulse"
      },
      {
        "id": "comprehension-pulse",
        "component": "knowledge_check",
        "question": "Which word describes a person who is very attentive to details and accuracy?",
        "options": [
          "Loquacious",
          "Ephemeral",
          "Fastidious",
          "Capricious"
        ],
        "correct": 2,
        "explanation": "Fastidious means showing or demanding excessive delicacy or care, or being highly attentive to details."
      }
    ]
  }
}
